        $nbr_customer = (int) Db::getInstance()->getValue(
            'SELECT count(*)
            FROM `' . _DB_PREFIX_ . 'customer`
            WHERE `id_shop`=' . (int) $id_shop
        );
        if ($nbr_customer) {
